export function isBundledR02TemplateId(templateId: string): boolean {
  return Object.prototype.hasOwnProperty.call(loaders, templateId)
}

/** 只有 Main 的固定索引能装载这些定义；外部仅提供精确 templateId。 */
export async function loadBundledR02Template(templateId: string): Promise<TemplateVersion> {
  const loader = loaders[templateId]
  if (!loader) throw new Error('R02_TEMPLATE_NOT_IN_BUNDLED_CATALOG')
  const {templateVersion} = await loader()
  const indexed = R02_TECHNICAL_CATALOG.find(item => item.templateId === templateId)
  if (!indexed || templateVersion.templateId !== templateId ||
      String(templateVersion.version) !== indexed.templateVersion) {
    throw new Error('R02_BUNDLED_TEMPLATE_IDENTITY_MISMATCH')
  }
  return templateVersion
}

